409	    } else if (strneq(opt, "g3", 2)) {
410	        processG3Options(opt);
411	        defcompression = COMPRESSION_CCITTFAX3;
412	    } else if (streq(opt, "g4"))
413	        defcompression = COMPRESSION_CCITTFAX4;
