123	/*
124	 * Given GeoKey, write out the KeyEntry entries, returning 0 if failure.
125	 *  This is the exact complement of ReadKey().
126	 */
127	
128	static int WriteKey(GTIF* gt, TempKeyData* tempData,
129	                    KeyEntry* entptr, GeoKey* keyptr)
130	{
131	    entptr->ent_key = (pinfo_t) keyptr->gk_key;
132	    entptr->ent_count = (pinfo_t) keyptr->gk_count;
133	    const int count = entptr->ent_count;
134	
135	    if (count==1 && keyptr->gk_type==TYPE_SHORT)
136	    {
137	        entptr->ent_location = GTIFF_LOCAL;
138	        memcpy(&(entptr->ent_val_offset), &keyptr->gk_data, sizeof(pinfo_t));
139	        return 1;
140	    }
141	
142	    switch (keyptr->gk_type)
143	    {
144	      case TYPE_SHORT:
145	        entptr->ent_location = GTIFF_GEOKEYDIRECTORY;
146	        entptr->ent_val_offset = (pinfo_t)
147	            ((pinfo_t*)keyptr->gk_data - gt->gt_short);
148	        break;
149	      case TYPE_DOUBLE:
150	        entptr->ent_location = GTIFF_DOUBLEPARAMS;
151	        entptr->ent_val_offset = (pinfo_t)
152	            ((double*)keyptr->gk_data - gt->gt_double);
153	        break;
154	      case TYPE_ASCII:
155	        if( tempData->tk_asciiParams == NULL )
156	            return 0;
157	        entptr->ent_location = GTIFF_ASCIIPARAMS;
158	        entptr->ent_val_offset = (pinfo_t) tempData->tk_asciiParamsOffset;
159	        _GTIFmemcpy (tempData->tk_asciiParams + tempData->tk_asciiParamsOffset
160	                     , keyptr->gk_data, keyptr->gk_count);
161	        tempData->tk_asciiParams[tempData->tk_asciiParamsOffset+keyptr->gk_count-1] = '|';
162	        tempData->tk_asciiParamsOffset += keyptr->gk_count;
163	        break;
164	      default:
165	        return 0; /* failure */
166	    }
167	
168	    return 1; /* success */
169	}
