172	/*
173	 * Numerically sort the GeoKeys.
174	 * We just do a linear search through
175	 * the list and pull out the keys that were set.
176	 */
177	
178	static int SortKeys(GTIF* gt,int *sortkeys)
179	{
180	    /* A bit convoluted to make Clang Static Analyzer happy */
181	    if( gt->gt_num_keys <= 0 )
182	        return 1;
183	
184	    sortkeys[0] = 1;
185	    for( int i = 1; i < gt->gt_num_keys; i++ )
186	        sortkeys[i] = i+1;
187	
188	    int did_work;
189	    do {  /* simple bubble sort */
190	        did_work = 0;
191	        for( int i = 0; i < gt->gt_num_keys-1; i++ )
192	        {
193	            if( gt->gt_keys[sortkeys[i]].gk_key
194	                > gt->gt_keys[sortkeys[i+1]].gk_key )
195	            {
196	                /* swap keys in sort list */
197	                int j = sortkeys[i];
198	                sortkeys[i] = sortkeys[i+1];
199	                sortkeys[i+1] = j;
200	
201	                did_work = 1;
202	            }
203	        }
204	    } while( did_work );
205	
206	    return 1;
207	}
