21:  ******************************************************************************
22:  *
23:  *  geo_simpletags.c  TIFF Interface module that just keeps track of the
24:  *                    tags in memory, without depending on libtiff.
25:  *
26:  *****************************************************************************/
27: 
28: #include <stdlib.h>
29: #include <string.h>
30: 
31: #include "geotiff.h"    /* public GTIFF interface */
32: #include "geo_simpletags.h"
33: 
34: #include "geo_tiffp.h"  /* Private TIFF interface */
35: 
36: static int ST_TypeSize( int st_type );
37: 
38: static int        _GTIFGetField (tiff_t *tif, pinfo_t tag, int *count, void *value );
39: static int        _GTIFSetField (tiff_t *tif, pinfo_t tag, int  count, void *value );
40: static tagtype_t  _GTIFTagType  (tiff_t *tif, pinfo_t tag);
41: 
42: /*
43:  * Set up default TIFF handlers.
44:  */
45: void GTIFSetSimpleTagsMethods(TIFFMethod *method)
46: {
47: 	if (!method) return;
48: 
49: 	method->get = _GTIFGetField;
50: 	method->set = _GTIFSetField;
51: 	method->type = _GTIFTagType;
52: }
53: 
54: /* returns the value of TIFF tag <tag>, or if
55:  * the value is an array, returns an allocated buffer
56:  * containing the values. Allocate a copy of the actual
57:  * buffer, sized up for updating.
58:  */
59: static int _GTIFGetField (tiff_t *tif, pinfo_t tag, int *count, void *val )
60: {
61:     int data_type;
62:     void *internal_value;
63:     if( !ST_GetKey( (ST_TIFF*) tif, (int) tag, count, &data_type,
64:                     &internal_value ) )
65:         return 0;
66: 
67:     if( data_type != ST_TagType( tag ) )
68:         return 0;
69: 
70:     const int item_size = ST_TypeSize( data_type );
71: 
72:     void *ret_value = (char *)_GTIFcalloc( *count * item_size );
73:     if (!ret_value) return 0;
74: 
75:     _TIFFmemcpy( ret_value, internal_value,  item_size * *count );
76: 
77:     *(void **)val = ret_value;
78:     return 1;
79: }
80: 
81: /*
82:  * Set a GeoTIFF TIFF field.
83:  */
84: static int _GTIFSetField (tiff_t *tif, pinfo_t tag, int count, void *value )
85: {
86:     const int st_type = ST_TagType( tag );
87: 
88:     return ST_SetKey( (ST_TIFF *) tif, (int) tag, count, st_type, value );
89: }
90: 
91: /*
92:  *  This routine is supposed to return the TagType of the <tag>
93:  *  TIFF tag. Unfortunately, "libtiff" does not provide this
94:  *  service by default, so we just have to "know" what type of tags
95:  *  we've got, and how many. We only define the ones Geotiff
96:  *  uses here, and others return UNKNOWN. The "tif" parameter
97:  *  is provided for those TIFF implementations that provide
98:  *  for tag-type queries.
99:  */
100: static tagtype_t  _GTIFTagType  (tiff_t *tif, pinfo_t tag)
101: {
102: 	(void) tif; /* dummy reference */
103: 
104: 	tagtype_t ttype;
105: 	switch (tag)
106: 	{
107: 		case GTIFF_ASCIIPARAMS:    ttype=TYPE_ASCII; break;
108: 		case GTIFF_PIXELSCALE:
109: 		case GTIFF_TRANSMATRIX:
110: 		case GTIFF_TIEPOINTS:
111: 		case GTIFF_DOUBLEPARAMS:   ttype=TYPE_DOUBLE; break;
112: 		case GTIFF_GEOKEYDIRECTORY: ttype=TYPE_SHORT; break;
113: 		default: ttype = TYPE_UNKNOWN;
114: 	}
115: 
116: 	return ttype;
117: }
118: 
119: /************************************************************************/
120: /*                             ST_TagType()                             */
121: /************************************************************************/
122: 
123: int ST_TagType( int tag )
124: {
125:     switch (tag)
126:     {
127:       case GTIFF_ASCIIPARAMS:
128:         return STT_ASCII;
129: 
130:       case GTIFF_PIXELSCALE:
131:       case GTIFF_TRANSMATRIX:
132:       case GTIFF_TIEPOINTS:
133:       case GTIFF_DOUBLEPARAMS:
134:         return STT_DOUBLE;
135: 
136:       case GTIFF_GEOKEYDIRECTORY:
137:         return STT_SHORT;
138:     }
139: 
140:     return -1;
141: }
142: 
143: 
144: /************************************************************************/
145: /*                            ST_TypeSize()                             */
146: /************************************************************************/
147: 
148: static int ST_TypeSize( int st_type )
149: 
150: {
151:     if( st_type == STT_ASCII )
152:         return 1;
153:     else if( st_type == STT_SHORT )
154:         return 2;
155:     else /* if( st_type == STT_DOUBLE ) */
156:         return 8;
157: }
158: 
159: /************************************************************************/
160: /*                             ST_Create()                              */
161: /************************************************************************/
162: 
163: ST_TIFF *ST_Create()
164: 
165: {
166:     return (ST_TIFF *) calloc(1,sizeof(ST_TIFF));
167: }
168: 
169: /************************************************************************/
170: /*                             ST_Destroy()                             */
171: /************************************************************************/
172: 
173: void ST_Destroy( ST_TIFF *st )
174: 
175: {
176:     for( int i = 0; i < st->key_count; i++ )
177:         free( st->key_list[i].data );
178: 
179:     if( st->key_list )
180:         free( st->key_list );
181:     free( st );
182: }
183: 
184: /************************************************************************/
185: /*                             ST_SetKey()                              */
186: /************************************************************************/
187: 
188: int ST_SetKey( ST_TIFF *st, int tag, int count, int st_type, void *data )
189: 
190: {
191: /* -------------------------------------------------------------------- */
192: /*      We should compute the length if we were not given a count       */
193: /* -------------------------------------------------------------------- */
194:     if (count == 0 && st_type == STT_ASCII )
195:     {
196:         count = (int)strlen((char*)data)+1;
197:     }
198: 
199: /* -------------------------------------------------------------------- */
200: /*      If we already have a value for this tag, replace it.            */
201: /* -------------------------------------------------------------------- */
202:     const int item_size = ST_TypeSize( st_type );
203:     for( int i = 0; i < st->key_count; i++ )
204:     {
205:         if( st->key_list[i].tag == tag )
206:         {
207:             free( st->key_list[i].data );
208:             st->key_list[i].count = count;
209:             st->key_list[i].type = st_type;
210:             /* +1 to make clang static analyzer not warn about potential malloc(0) */
211:             st->key_list[i].data = malloc(item_size*count+1);
212:             memcpy( st->key_list[i].data, data, count * item_size );
213:             return 1;
214:         }
215:     }
216: 
217: /* -------------------------------------------------------------------- */
218: /*      Otherwise, add a new entry.                                     */
219: /* -------------------------------------------------------------------- */
220:     st->key_count++;
221:     st->key_list = (ST_KEY *) realloc(st->key_list,
222:                                       sizeof(ST_KEY) * st->key_count);
223:     st->key_list[st->key_count-1].tag = tag;
224:     st->key_list[st->key_count-1].count = count;
225:     st->key_list[st->key_count-1].type = st_type;
226:     /* +1 to make clang static analyzer not warn about potential malloc(0) */
227:     st->key_list[st->key_count-1].data = malloc(item_size * count+1);
228:     memcpy( st->key_list[st->key_count-1].data, data, item_size * count );
229: 
230:     return 1;
231: }
232: 
233: /************************************************************************/
234: /*                             ST_GetKey()                              */
235: /************************************************************************/
236: 
237: int ST_GetKey( ST_TIFF *st, int tag, int *count,
238:                int *st_type, void **data_ptr )
239: 
240: {
241:     for( int i = 0; i < st->key_count; i++ )
242:     {
243:         if( st->key_list[i].tag == tag )
244:         {
245:             if( count )
246:                 *count = st->key_list[i].count;
247:             if( st_type )
248:                 *st_type = st->key_list[i].type;
249:             if( data_ptr )
250:                 *data_ptr = st->key_list[i].data;
251:             return 1;
252:         }
253:     }
254: 
255:     return 0;
256: }

